      if (r.type) facts.push(r.type === 'create' ? 'new file' : 'overwrote')
      nonEmpty(i.content).slice(0, 4).forEach((t) => lines.push({ t: clipLine(t), k: 'add' }))
      return { head: `Write ${rel(i.file_path, cwd)}`, facts, lines }
    }
